import java.util.*;

class Solution {
    public int totalFruit(int[] trees) {
        Map<Integer, Integer> count = new HashMap<>();
        int left = 0, best = 0;
        for (int right = 0; right < trees.length; right++) {
            count.merge(trees[right], 1, Integer::sum);
            while (count.size() > 2) {          // a third type: shrink from the left
                int t = trees[left++];
                if (count.merge(t, -1, Integer::sum) == 0) count.remove(t);
            }
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

