    def totalFruit(self, trees: List[int]) -> int:
        cnt = Counter(); l = best = 0
        for r, x in enumerate(trees):
            cnt[x] += 1
            while len(cnt) > 2:
                cnt[trees[l]] -= 1
                if cnt[trees[l]] == 0: del cnt[trees[l]]
                l += 1
            best = max(best, r - l + 1)
